$user=require_login();$pageTitle='My profile';$errors=[];$fullName=$user['full_name'];$department=$user['department']??'';$graduationYear=$user['graduation_year']??'';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$fullName=trim((string)($_POST['full_name']??''));$department=trim((string)($_POST['department']??''));$graduationYear=trim((string)($_POST['graduation_year']??''));$current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');
 if(strlen($fullName)<2||strlen($fullName)>120)$errors[]='Name must be between 2 and 120 characters.';
 if(strlen($department)>120)$errors[]='Department must be 120 characters or fewer.';
 if($graduationYear!==''&&(!ctype_digit($graduationYear)||(int)$graduationYear<1950||(int)$graduationYear>(int)date('Y')+8))$errors[]='Enter a valid graduation year.';
 if($new!==''){if(strlen($new)<10)$errors[]='New password must be at least 10 characters.';if($new!==$confirm)$errors[]='New password confirmation does not match.';if($current==='')$errors[]='Enter your current password to change it.';}
 if(!$errors){try{$d=db();if($new!==''){$s=$d->prepare('SELECT password_hash FROM users WHERE id=?');$s->execute([(int)$user['id']]);$h=$s->fetchColumn();if(!$h||!password_verify($current,(string)$h))$errors[]='Your current password is incorrect.';}
 if(!$errors){if($new!==''){$s=$d->prepare('UPDATE users SET full_name=?,department=?,graduation_year=?,password_hash=? WHERE id=?');$s->execute([$fullName,$department?:null,$graduationYear!==''?(int)$graduationYear:null,password_hash($new,PASSWORD_DEFAULT),(int)$user['id']]);}else{$s=$d->prepare('UPDATE users SET full_name=?,department=?,graduation_year=? WHERE id=?');$s->execute([$fullName,$department?:null,$graduationYear!==''?(int)$graduationYear:null,(int)$user['id']]);}set_flash('success','Your profile has been updated.');redirect('profile.php');}}
 catch(PDOException $x){error_log('Profile update: '.$x->getMessage());$errors[]='Could not update your profile. Please try again.';}}
}
